// ---- sdk/php/src/Runtime/Json.php ----

// Strict JSON admission for the adapter SDK (issue #106): closed
// parsing with duplicate-key, trailing-document, explicit-null, and
// non-finite refusals, plus the canonical byte serializer the wire
// requires (byte-sorted keys, compact, no trailing LF).

final class Json {
    /** Raw lexer pass: duplicated key spellings, if any. Duplicates
     * inside map-typed member positions (`$allowContainerPaths`, issue
     * #106 review r5 #9 — production's serde `BTreeMap` takes
     * last-wins) are not offenders: json_decode already keeps the last
     * value, exactly like production. */
    public static function duplicateKeys(string $text, array $allowContainerPaths = []): array {
        $offenders = [];
        $stack = [['keys' => null, 'path' => '', 'lastKey' => null]];
        $index = 0;
        $length = strlen($text);
        $skip = function () use (&$index, $text, $length): void {
            while ($index < $length && in_array($text[$index], [' ', "\t", "\r", "\n"], true)) {
                $index++;
            }
        };
        while ($index < $length) {
            $ch = $text[$index];
            if ($ch === '"') {
                $start = $index;
                $index++;
                while ($index < $length) {
                    $c = $text[$index];
                    if ($c === '\\') {
                        $index += 2;
                        continue;
                    }
                    if ($c === '"') {
                        $index++;
                        break;
                    }
                    $index++;
                }
                $raw = substr($text, $start, $index - $start);
                $key = json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
                $skip();
                if ($index < $length && $text[$index] === ':') {
                    $index++;
                    $frame = $stack[count($stack) - 1];
                    if ($frame['keys'] !== null) {
                        $policy = $allowContainerPaths[$frame['path']] ?? null;
                        $allowed = in_array($frame['path'], $allowContainerPaths, true);
                        if (is_callable($policy)) {
                            // Serde validates every map value before inserting it;
                            // last-wins must not hide a malformed earlier value.
                            $probe = $index;
                            self::skipJsonWhitespace($text, $probe);
                            $startValue = $probe;
                            $objects = []; $zeros = [];
                            self::auditValue($text, $probe, '', $objects, $zeros);
                            $current = json_decode(substr($text, $startValue, $probe - $startValue), true, 128, JSON_THROW_ON_ERROR);
                            $allowed = $policy($frame['values'][$key] ?? null, $current);
                            $stack[count($stack) - 1]['values'][$key] = $current;
                        }
                        if (isset($frame['keys'][$key]) && !$allowed) {
                            $offenders[] = $key;
                        }
                        $stack[count($stack) - 1]['keys'][$key] = true;
                    }
                    $stack[count($stack) - 1]['lastKey'] = $key;
                }
                continue;
            }
            if ($ch === '{') {
                $parent = $stack[count($stack) - 1];
                $stack[] = ['keys' => [], 'path' => self::childMemberPath($parent), 'lastKey' => null];
                $index++;
                continue;
            }
            if ($ch === '[') {
                $parent = $stack[count($stack) - 1];
                $stack[] = ['keys' => null, 'path' => self::childMemberPath($parent), 'lastKey' => null];
                $index++;
                continue;
            }
            if ($ch === '}' || $ch === ']') {
                if (count($stack) > 1) {
                    array_pop($stack);
                }
                $index++;
                continue;
            }
            $index++;
        }
        return $offenders;
    }

    /** The member-name path of a child container: object children carry
     * their key (arrays do not — their elements share the array's
     * member path). */
    private static function childMemberPath(array $parent): string {
        if ($parent['lastKey'] === null) {
            return $parent['path'];
        }
        return $parent['path'] === '' ? $parent['lastKey'] : $parent['path'] . '.' . $parent['lastKey'];
    }

    /** The index of the closing bracket of the first document, or -1. */
    private static function documentEnd(string $text): int {
        $depth = 0;
        $inString = false;
        $escaped = false;
        $length = strlen($text);
        for ($index = 0; $index < $length; $index++) {
            $ch = $text[$index];
            if ($inString) {
                if ($escaped) {
                    $escaped = false;
                } elseif ($ch === '\\') {
                    $escaped = true;
                } elseif ($ch === '"') {
                    $inString = false;
                }
                continue;
            }
            if ($ch === '"') {
                $inString = true;
            } elseif ($ch === '{' || $ch === '[') {
                $depth++;
            } elseif ($ch === '}' || $ch === ']') {
                $depth--;
                if ($depth === 0) {
                    return $index;
                }
            }
        }
        return -1;
    }

    private const JSON_WHITESPACE = " \t\r\n";

    /** Strict parse of one complete JSON document (object or array).
     * Only JSON whitespace (space, tab, CR, LF) may surround the
     * document (issue #106 review r4 #4): bare ltrim/trim also strip
     * NUL and vertical tab, admitting control bytes the host's parser
     * refuses. Nesting depth is bounded like the host's parser (issue
     * #106 review r4 #5) through json_decode's depth argument. The
     * parse result also carries the raw-lexeme audit (issue #106 review
     * r4 #3): the member paths whose raw value is a JSON object and
     * whose raw number lexeme is `-0` — the two distinctions
     * json_decode's associative mapping collapses and production's
     * typed decoder refuses. `$allowDuplicateContainers` (issue #106
     * review r5 #9) admits duplicate keys inside map-typed member
     * positions (last-wins, like production's serde `BTreeMap`). */
    public static function strictParse(string $text, array $allowDuplicateContainers = []): array {
        if (str_starts_with($text, "\xEF\xBB\xBF")) {
            return ['ok' => false, 'reason' => 'not-json'];
        }
        $trimmed = ltrim($text, self::JSON_WHITESPACE);
        $first = $trimmed === '' ? '' : $trimmed[0];
        if ($first !== '{' && $first !== '[') {
            return ['ok' => false, 'reason' => 'not-json'];
        }
        $end = self::documentEnd($trimmed);
        if ($end === -1) {
            return ['ok' => false, 'reason' => 'not-json'];
        }
        if (strlen(rtrim(substr($trimmed, $end + 1), self::JSON_WHITESPACE)) > 0) {
            return ['ok' => false, 'reason' => 'trailing-document'];
        }
        $document = substr($trimmed, 0, $end + 1);
        try {
            $value = json_decode($document, true, 128, JSON_THROW_ON_ERROR);
        } catch (\JsonException $e) {
            return ['ok' => false, 'reason' => 'not-json'];
        }
        if (count(self::duplicateKeys($document, $allowDuplicateContainers)) > 0) {
            return ['ok' => false, 'reason' => 'duplicate-key'];
        }
        $objectPaths = [];
        $zeroPaths = [];
        $auditIndex = 0;
        self::auditValue($document, $auditIndex, '', $objectPaths, $zeroPaths);
        return ['ok' => true, 'value' => $value, 'objectPaths' => array_keys($objectPaths), 'zeroPaths' => array_keys($zeroPaths)];
    }

    private static function skipJsonWhitespace(string $text, int &$index): void {
        $length = strlen($text);
        while ($index < $length && strpos(self::JSON_WHITESPACE, $text[$index]) !== false) {
            $index++;
        }
    }

    /** Consume one quoted JSON string starting at $index; returns the
     * decoded text or null when json_decode refuses the token. */
    private static function auditString(string $text, int &$index): ?string {
        $start = $index;
        $index++;
        $length = strlen($text);
        while ($index < $length) {
            $c = $text[$index];
            if ($c === '\\') {
                $index += 2;
                continue;
            }
            if ($c === '"') {
                $index++;
                break;
            }
            $index++;
        }
        try {
            return json_decode(substr($text, $start, $index - $start), true, 2, JSON_THROW_ON_ERROR);
        } catch (\JsonException) {
            return null;
        }
    }

    /** Structural walk over one ALREADY-VALID raw document recording the
     * member paths whose raw value is a JSON object (list-position
     * members must refuse them: `{}` and `{"0":…}` decode to list
     * values) and whose raw number lexeme is `-0` (json_decode maps it
     * to int 0; production's serde u64 visitor refuses the signed
     * spelling). Paths join member names and array indices with dots. */
    private static function auditValue(string $text, int &$index, string $path, array &$objectPaths, array &$zeroPaths): void {
        self::skipJsonWhitespace($text, $index);
        if ($index >= strlen($text)) {
            return;
        }
        $c = $text[$index];
        if ($c === '{') {
            $objectPaths[$path] = true;
            $index++;
            self::skipJsonWhitespace($text, $index);
            if (substr($text, $index, 1) === '}') {
                $index++;
                return;
            }
            for (;;) {
                self::skipJsonWhitespace($text, $index);
                if (substr($text, $index, 1) !== '"') {
                    return;
                }
                $key = self::auditString($text, $index);
                if ($key === null) {
                    return;
                }
                self::skipJsonWhitespace($text, $index);
                if (substr($text, $index, 1) !== ':') {
                    return;
                }
                $index++;
                self::auditValue($text, $index, $path === '' ? $key : $path . '.' . $key, $objectPaths, $zeroPaths);
                self::skipJsonWhitespace($text, $index);
                $next = substr($text, $index, 1);
                if ($next === ',') {
                    $index++;
                    continue;
                }
                if ($next === '}') {
                    $index++;
                }
                return;
            }
        }
        if ($c === '[') {
            $index++;
            self::skipJsonWhitespace($text, $index);
            if (substr($text, $index, 1) === ']') {
                $index++;
                return;
            }
            for ($element = 0; ; $element++) {
                self::auditValue($text, $index, $path === '' ? (string) $element : $path . '.' . $element, $objectPaths, $zeroPaths);
                self::skipJsonWhitespace($text, $index);
                $next = substr($text, $index, 1);
                if ($next === ',') {
                    $index++;
                    continue;
                }
                if ($next === ']') {
                    $index++;
                }
                return;
            }
        }
        if ($c === '"') {
            self::auditString($text, $index);
            return;
        }
        foreach (['true', 'false', 'null'] as $literal) {
            if (substr($text, $index, strlen($literal)) === $literal) {
                $index += strlen($literal);
                return;
            }
        }
        // A number lexeme: `-0` is the negative-zero integer spelling
        // json_decode collapses to an accepted int 0.
        $start = $index;
        $length = strlen($text);
        while ($index < $length && strpos('0123456789+-.eE', $text[$index]) !== false) {
            $index++;
        }
        if (substr($text, $start, $index - $start) === '-0') {
            $zeroPaths[$path] = true;
        }
    }

    /** Read exactly one bounded JSON object document. */
    public static function readSingleObject(string $text, int $maxBytes, array $allowDuplicateContainers = []): array {
        if (strlen($text) > $maxBytes) {
            return ['ok' => false, 'reason' => 'oversize'];
        }
        $parsed = self::strictParse($text, $allowDuplicateContainers);
        if (!$parsed['ok']) {
            return $parsed;
        }
        if (!is_array($parsed['value']) || array_is_list($parsed['value'])) {
            return ['ok' => false, 'reason' => 'shape'];
        }
        return $parsed;
    }

    /** Canonical compact JSON: sorted keys, no whitespace, no trailing LF. */
    public static function canonicalJson(mixed $value): string {
        if (is_array($value)) {
            if (array_is_list($value)) {
                $items = array_map([self::class, 'canonicalJson'], $value);
                return '[' . implode(',', $items) . ']';
            }
            $keys = array_keys($value);
            sort($keys, SORT_STRING);
            $members = [];
            foreach ($keys as $key) {
                $members[] = json_encode((string) $key, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . ':' . self::canonicalJson($value[$key]);
            }
            return '{' . implode(',', $members) . '}';
        }
        return json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }
}

// ---- sdk/php/src/Runtime/Ids.php ----

// Deterministic identifiers and digest grammar (issue #106).

final class Ids {
    public const REQUEST_ID_PREFIX = 'req-';
    public const PLAN_ID_PREFIX = 'plan-';

    /** Lowercase hex SHA-256 of the UTF-8 bytes of the text. */
    public static function sha256Hex(string $text): string {
        return hash('sha256', $text);
    }

    /** The `sha256:<64 hex>` digest spelling. */
    public static function sha256(string $text): string {
        return 'sha256:' . self::sha256Hex($text);
    }

    private static function prefixedHex(mixed $value, string $prefix): bool {
        if (!is_string($value)) {
            return false;
        }
        $hex = substr($value, 0, strlen($prefix)) === $prefix ? substr($value, strlen($prefix)) : null;
        if ($hex === null || strlen($hex) !== 64) {
            return false;
        }
        return preg_match('/^[0-9a-f]{64}$/', $hex) === 1;
    }

    public static function isSha256Digest(mixed $value): bool {
        return self::prefixedHex($value, 'sha256:');
    }

    public static function isRequestId(mixed $value): bool {
        return self::prefixedHex($value, self::REQUEST_ID_PREFIX);
    }

    public static function isPlanId(mixed $value): bool {
        return self::prefixedHex($value, self::PLAN_ID_PREFIX);
    }

    /** The deterministic request id over the envelope sans request_id. */
    public static function requestId(array $envelope): string {
        unset($envelope['request_id']);
        return self::REQUEST_ID_PREFIX . self::sha256Hex(Json::canonicalJson($envelope));
    }

    /** The deterministic plan id over the canonical bytes of one plan. */
    public static function planId(array $entries): string {
        return self::PLAN_ID_PREFIX . self::sha256Hex(Json::canonicalJson($entries));
    }
}

// ---- sdk/php/src/Runtime/Paths.php ----

// Logical path, scope, and protected-home helpers (issue #106):
// defense in depth mirroring the host's closed grammar. The NFC table
// check stays host-owned; vectors mark it requiresNfc and PHP runtimes
// skip those vectors explicitly.

final class Paths {
    private const MAX_VALUE_BYTES = 512;
    private const MAX_SEGMENT_BYTES = 64;

    private const PROTECTED_HOMES = [
        'lekalo-model' => ['lekalo'],
        'lekalo-lockfile' => ['lekalo.lock'],
        'ir' => ['.lekalo', 'ir'],
        'cache' => ['.lekalo', 'cache'],
        'import' => ['.lekalo', 'import'],
        'privacy' => ['.lekalo', 'privacy'],
        'consumer' => ['.lekalo', 'consumer'],
        'openspec' => ['openspec'],
    ];

    private const DOS_DEVICES = [
        'CON', 'PRN', 'AUX', 'NUL', 'COM1', 'COM2', 'COM3', 'COM4', 'COM5', 'COM6', 'COM7', 'COM8',
        'COM9', 'LPT1', 'LPT2', 'LPT3', 'LPT4', 'LPT5', 'LPT6', 'LPT7', 'LPT8', 'LPT9',
    ];

    /** The closed host path-violation reason, or null. */
    public static function pathViolation(string $path): ?string {
        if ($path === '') {
            return 'structure.path-empty';
        }
        if ($path[0] === '/' || str_starts_with($path, '\\\\') || str_starts_with($path, '//')) {
            return 'structure.path-absolute';
        }
        if ($path[0] === '~' || self::isDriveOrScheme($path)) {
            return 'structure.path-absolute';
        }
        if (str_contains($path, '\\') || self::containsPercentEscape($path) || str_contains($path, ':')) {
            return 'structure.path-escape';
        }
        foreach (explode('/', $path) as $segment) {
            if ($segment === '' || strlen($segment) > 64) {
                return 'structure.path-segment';
            }
            if ($segment === '.' || $segment === '..' || str_ends_with($segment, '.') || str_ends_with($segment, ' ')) {
                return 'structure.path-traversal';
            }
            if (in_array(self::dosStem($segment), self::DOS_DEVICES, true)) {
                return 'structure.path-device';
            }
            if (self::containsShortName($segment)) {
                return 'structure.path-short-name';
            }
            if (preg_match('/[A-Z]/', $segment) === 1) {
                return 'structure.path-case';
            }
        }
        return null;
    }

    private static function isDriveOrScheme(string $path): bool {
        if (strlen($path) >= 2 && ctype_alpha($path[0]) && $path[1] === ':') {
            return true;
        }
        $colon = strpos($path, ':');
        if ($colon === false || $colon === 0) {
            return false;
        }
        $stem = substr($path, 0, $colon);
        if (!ctype_lower($stem[0])) {
            return false;
        }
        return preg_match('/^[a-z0-9+.-]+\z/', $stem) === 1;
    }

    private static function dosStem(string $segment): string {
        $dot = strpos($segment, '.');
        $stem = $dot === false ? $segment : substr($segment, 0, $dot);
        return strtoupper($stem);
    }

    private static function containsShortName(string $segment): bool {
        $tilt = strpos($segment, '~');
        if ($tilt === false || $tilt < 1 || $tilt > 6 || $tilt + 1 >= strlen($segment)) {
            return false;
        }
        return ctype_digit($segment[$tilt + 1]);
    }

    private static function containsPercentEscape(string $path): bool {
        return preg_match('/%[0-9a-fA-F]{2}/', $path) === 1;
    }

    private static function segmentOk(string $segment): bool {
        if ($segment === '.' || $segment === '..' || str_ends_with($segment, '.')) {
            return false;
        }
        $portable = str_starts_with($segment, '.') ? 'x' . substr($segment, 1) : $segment;
        if (self::pathViolation($portable) !== null) {
            return false;
        }
        if ($segment === '' || strlen($segment) > self::MAX_SEGMENT_BYTES) {
            return false;
        }
        $first = $segment[0];
        if (!(($first >= 'a' && $first <= 'z') || ($first >= '0' && $first <= '9') || $first === '.')) {
            return false;
        }
        return preg_match('/^[a-z0-9._-]*\z/', $segment) === 1;
    }

    /** @return list<string>|null */
    private static function segments(mixed $value): ?array {
        if (!is_string($value) || $value === '' || strlen($value) > self::MAX_VALUE_BYTES || $value[0] === '/') {
            return null;
        }
        $parts = explode('/', $value);
        foreach ($parts as $part) {
            if ($part === '') {
                return null;
            }
        }
        return $parts;
    }

    public static function isLogicalPath(mixed $value): bool {
        $parts = self::segments($value);
        if ($parts === null) {
            return false;
        }
        foreach ($parts as $part) {
            if (!self::segmentOk($part)) {
                return false;
            }
        }
        return true;
    }

    public static function isScope(mixed $value): bool {
        $parts = self::segments($value);
        if ($parts === null) {
            return false;
        }
        $last = $parts[count($parts) - 1];
        $head = array_slice($parts, 0, -1);
        if ($last === '**') {
            if (count($head) === 0) {
                return false;
            }
            foreach ($head as $part) {
                if (!self::segmentOk($part)) {
                    return false;
                }
            }
            return true;
        }
        foreach ($parts as $part) {
            if (!self::segmentOk($part)) {
                return false;
            }
        }
        return true;
    }

    public static function scopeCovers(string $scope, string $path): bool {
        if (!self::isScope($scope) || !self::isLogicalPath($path)) {
            return false;
        }
        $scopeParts = self::segments($scope);
        $pathParts = self::segments($path);
        $recursive = $scopeParts[count($scopeParts) - 1] === '**';
        $prefix = $recursive ? array_slice($scopeParts, 0, -1) : $scopeParts;
        if (count($pathParts) < count($prefix)) {
            return false;
        }
        foreach ($prefix as $index => $part) {
            if ($pathParts[$index] !== $part) {
                return false;
            }
        }
        if ($recursive) {
            return count($pathParts) > count($prefix);
        }
        return count($pathParts) === count($prefix);
    }

    public static function protectedHome(string $path): ?string {
        $parts = self::segments($path);
        if ($parts === null) {
            return null;
        }
        foreach (self::PROTECTED_HOMES as $name => $home) {
            if (count($parts) >= count($home) && self::equalPrefix($parts, $home)) {
                return $name;
            }
        }
        return null;
    }

    public static function scopeTouchesProtectedHome(string $scope): ?string {
        $parts = self::segments($scope);
        if ($parts === null) {
            return null;
        }
        $recursive = $parts[count($parts) - 1] === '**';
        $prefix = $recursive ? array_slice($parts, 0, -1) : $parts;
        foreach (self::PROTECTED_HOMES as $name => $home) {
            $inside = count($prefix) >= count($home) && self::equalPrefix($prefix, $home);
            $above = count($prefix) <= count($home) && self::equalPrefix($home, $prefix);
            if ($inside || $above) {
                return $name;
            }
        }
        return null;
    }

    /** @param list<string> $parts @param list<string> $prefix */
    private static function equalPrefix(array $parts, array $prefix): bool {
        if (count($parts) < count($prefix)) {
            return false;
        }
        foreach ($prefix as $index => $part) {
            if ($parts[$index] !== $part) {
                return false;
            }
        }
        return true;
    }

    public static function isToken(mixed $value): bool {
        if (!is_string($value) || $value === '' || strlen($value) > 64) {
            return false;
        }
        return preg_match('/^[a-z][a-z0-9-]*\z/', $value) === 1;
    }

    /** The manifest-local semantic-id grammar (core
     * trace::id::is_semantic_id, issue #106 review r3 #8): scan-entry
     * evidence reference targets — non-empty, at most 192 bytes, ASCII
     * alphanumeric or `_.:-`, starting alphanumeric or underscore. The
     * SDK used to enforce a length bound only, admitting slash-path
     * targets the production response decoder refuses. */
    public static function isSemanticId(mixed $value): bool {
        if (!is_string($value) || $value === '' || strlen($value) > 192) {
            return false;
        }
        return preg_match('/^[A-Za-z0-9_][A-Za-z0-9_.:-]*\z/', $value) === 1;
    }

    /** The production ai-lint identifier grammar (issue #106 review r3
     * #5): core ai_lint::input::token gates the lint scope items,
     * binding nativeId/symbol, and the revision pin's known value —
     * non-empty, at most 256 bytes, ASCII alphanumeric or
     * `_.:/#@\\-`, starting alphanumeric. The SDK used to enforce a
     * length bound only. */
    public static function isWireToken(mixed $value): bool {
        if (!is_string($value) || $value === '' || strlen($value) > 256) {
            return false;
        }
        return preg_match('/^[A-Za-z0-9][A-Za-z0-9_.:\/#@\\\\-]*\z/', $value) === 1;
    }

    public static function isCapabilityId(mixed $value): bool {
        if (!is_string($value) || $value === '' || strlen($value) > 128) {
            return false;
        }
        foreach (explode('.', $value) as $segment) {
            if ($segment === '' || strlen($segment) > 128) {
                return false;
            }
            $first = $segment[0];
            if (!(($first >= 'a' && $first <= 'z') || ($first >= '0' && $first <= '9'))) {
                return false;
            }
            if (preg_match('/^[a-z0-9_-]+\z/', $segment) !== 1) {
                return false;
            }
        }
        return true;
    }

    public static function isContractVersion(mixed $value): bool {
        if (!is_string($value) || $value === '' || strlen($value) > 32) {
            return false;
        }
        $parts = explode('.', $value);
        if (count($parts) !== 3) {
            return false;
        }
        foreach ($parts as $part) {
            if ($part === '' || !ctype_digit($part)) {
                return false;
            }
        }
        return true;
    }

    /** @param list<string> $writeScopes */
    public static function planScopeViolation(string $path, array $writeScopes): ?string {
        $home = self::protectedHome($path);
        if ($home !== null) {
            return "protected-path:{$home}";
        }
        foreach ($writeScopes as $scope) {
            if (self::scopeCovers($scope, $path)) {
                return null;
            }
        }
        return 'scope:uncovered';
    }
}

